"""Offline init compatibility: same resolved path, exact complete generated bytes.

Only the native CLI is executed externally. Python runs in-process as the oracle
(fork-only for resource limits); --oracle-only validates the corpus independently.
"""
import argparse
import contextlib
from datetime import datetime
import io
import json
import os
from pathlib import Path
import re
import resource
import select
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
import tomllib
import traceback
from unittest import mock
import uuid

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
sys.dont_write_bytecode = True
from runner import actions, coven, storage, task_attempts, task_ledger

ENV = {k: v for k, v in os.environ.items() if not k.startswith("COVEN_")}
ENV.update(COVEN_COMMAND="/deterministic tools/coven's cli", PYTHONDONTWRITEBYTECODE="1")
CHILDREN = set()
FLAGS = ((), ("--force",), ("--blank",), ("--force", "--blank"))
RESERVED = ("coven.json", "coven.toml", "goal.md", "spec.md", "dashboard.md",
            "agents", "prompts", "state", "logs", "checkpoints", "work", "output", "tmux")
RESERVED_ERROR = r"Refusing to initialize|init_reserved_entry_exists_force_does_not_authorize_reset"


class CorpusTimeout(BaseException):
    """Do not let per-case failure collection swallow the total watchdog."""


def snapshot(root):
    """Include root metadata; never follow symlinks or open special files."""
    result = {}
    for path in [root, *sorted(root.rglob("*"))]:
        meta = path.lstat()
        if stat.S_ISLNK(meta.st_mode):
            kind, data = "link", os.readlink(path)
        elif stat.S_ISDIR(meta.st_mode):
            kind, data = "dir", None
        elif stat.S_ISREG(meta.st_mode):
            kind, data = "file", path.read_bytes()
        elif stat.S_ISFIFO(meta.st_mode):
            kind, data = "fifo", None
        else:
            raise AssertionError(f"unexpected fixture type: {path}")
        result[str(path.relative_to(root))] = (
            kind, stat.S_IMODE(meta.st_mode), data, meta.st_ino, meta.st_mtime_ns)
    return result


def restore(root, saved):
    for path in root.iterdir():
        if path.is_dir() and not path.is_symlink():
            shutil.rmtree(path)
        else:
            path.unlink()
    for relative, (kind, mode, data, _, _) in saved.items():
        path = root / relative
        if relative == ".":
            continue
        if kind == "dir":
            path.mkdir()
        elif kind == "link":
            path.symlink_to(data)
        elif kind == "file":
            path.write_bytes(data)
        elif kind == "fifo":
            os.mkfifo(path, mode)
        if kind != "link":
            path.chmod(mode)


def python(args, cwd, env):
    out, err = io.StringIO(), io.StringIO()
    with mock.patch.dict(os.environ, env, clear=True), contextlib.chdir(cwd), \
            contextlib.redirect_stdout(out), contextlib.redirect_stderr(err), \
            mock.patch.object(subprocess, "Popen", side_effect=AssertionError("oracle external execution")):
        try:
            code = coven.main(list(map(str, args)))
        except SystemExit as exc:
            code = exc.code
        except Exception:
            # Model the standalone Python CLI's exit for unhandled input errors
            # (notably --example=""), without spawning a Python subprocess.
            traceback.print_exc()
            code = 1
    return code, out.getvalue(), err.getvalue()


def stop(child):
    try:
        if child.poll() is None:
            try:
                os.killpg(child.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        child.communicate(timeout=2)
    finally:
        CHILDREN.discard(child)


def limit_file_size():
    signal.signal(signal.SIGXFSZ, signal.SIG_IGN)
    _, hard = resource.getrlimit(resource.RLIMIT_FSIZE)
    resource.setrlimit(resource.RLIMIT_FSIZE, (128, hard))


def limited_python(args, cwd, env):
    """Isolate irreversible resource limits without executing another Python."""
    reader, writer = os.pipe()
    try:
        pid = os.fork()
    except BaseException:
        os.close(reader)
        os.close(writer)
        raise
    if pid == 0:
        try:
            os.close(reader)
            signal.signal(signal.SIGALRM, signal.SIG_DFL)
            signal.alarm(6)
            try:
                limit_file_size()
                result = python(args, cwd, env)
            except BaseException:
                result = (-1, "", traceback.format_exc())
            payload = json.dumps(result).encode()
            assert len(payload) < 4096, "fork result exceeds atomic pipe bound"
            assert os.write(writer, payload) == len(payload)
        finally:
            os._exit(0)
    os.close(writer)
    try:
        assert select.select([reader], [], [], 7)[0], "forked oracle timed out"
        payload = os.read(reader, 4096)
        assert payload, "forked oracle exited without a result"
        return tuple(json.loads(payload))
    finally:
        os.close(reader)
        try:
            os.kill(pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        os.waitpid(pid, 0)


def generated_sequence(workspace):
    """Read only generated scalar fields, not arbitrary matching UUID/text."""
    team = json.loads((workspace / "coven.json").read_bytes())
    tasks = json.loads((workspace / "state/tasks.json").read_bytes())
    events = [json.loads(line) for line in (workspace / "logs/events.jsonl").read_bytes().splitlines()]
    stamps = [team["created_at"]]
    stamps += [task[field] for task in tasks for field in ("created_at", "updated_at")]
    stamps += [event["ts"] for event in events]
    dates = []
    for value in stamps:
        assert re.fullmatch(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)", value), value
        dates.append(datetime.fromisoformat(value.replace("Z", "+00:00")))
    assert dates == sorted(dates), "generated timestamps went backwards"
    ids = [event["event_id"] for event in events]
    assert len(ids) == len(set(ids)), "event IDs reused"
    for value in ids:
        parsed = uuid.UUID(value)
        assert str(parsed) == value and parsed.version == 4 and parsed.variant == uuid.RFC_4122, value
    assert events[0]["type"] == "workspace.created"
    assert events[0]["name"] == team["name"] and events[0]["agents"] == team["agents"]
    if team["example"] is None:
        assert not tasks and len(events) == 1 and events[0]["example"] == "blank"
    else:
        assert events[0]["example"] == team["example"]
        assert events[1]["type"] == "goal.seeded" and events[1]["example"] == team["example"]
        assert len(events) == len(tasks) + 2
        assert [event["task"] for event in events[2:] if event["type"] == "task.seeded"] == tasks
    return stamps, [uuid.UUID(value) for value in ids]


class Suite:
    def __init__(self, root, binary, oracle_only):
        self.root, self.binary, self.oracle_only = root, binary, oracle_only
        self.serial, self.count, self.failures = 0, 0, []

    def run(self, label, fn):
        self.count += 1
        try:
            fn()
        except Exception as exc:
            self.failures.append(f"{label}: {type(exc).__name__}: {exc}")
        finally:
            for child in tuple(CHILDREN):
                stop(child)

    def fixture(self):
        self.serial += 1
        case = self.root / str(self.serial)
        case.mkdir()
        cwd = case / "cwd"
        cwd.mkdir()
        return case, cwd, case / "workspace with spaces"

    def candidate(self, args, cwd, env, limited=False):
        if self.oracle_only:
            return (limited_python if limited else python)(args, cwd, env)
        child = subprocess.Popen([self.binary, *map(str, args)], cwd=cwd, env=env,
                                 stdin=subprocess.DEVNULL, stdout=subprocess.PIPE,
                                 stderr=subprocess.PIPE, start_new_session=True,
                                 preexec_fn=limit_file_size if limited else None)
        CHILDREN.add(child)
        try:
            out, err = child.communicate(timeout=6)
            return child.returncode, out.decode(), err.decode()
        finally:
            stop(child)

    def success(self, extra=(), path_kind="missing", overrides=None, mask=0o022, interop=False,
                workspace_literal=None, terminator=False):
        case, cwd, workspace = self.fixture()
        env = {**ENV, **(overrides or {})}
        operand = str(workspace)
        if path_kind == "nested":
            workspace = case / "missing" / "nested" / "workspace"
            operand = str(workspace)
        elif path_kind == "unicode":
            workspace = case / "spaces \u03bb \U0001f680"
            operand = str(workspace)
        elif path_kind == "dotdot":
            operand = str(case / "absent" / "deeper" / ".." / ".." / "workspace")
            workspace = case / "workspace"
        elif path_kind in ("cwd", "dot", "empty"):
            workspace = cwd
            operand = {"cwd": None, "dot": ".", "empty": ""}[path_kind]
        elif path_kind == "relative":
            operand = "../workspace with spaces"
        elif path_kind == "tilde":
            env["HOME"] = str(case)
            operand = "~/chosen home"
            workspace = case / "chosen home"
        elif path_kind in ("symlink-root", "dangling-root"):
            if path_kind == "symlink-root":
                workspace.mkdir()
            link = case / "alias"
            link.symlink_to(workspace, target_is_directory=True)
            operand = str(link)
        elif path_kind == "symlink-parent":
            parent = case / "real parent"
            parent.mkdir()
            link = case / "alias"
            link.symlink_to(parent, target_is_directory=True)
            operand = str(link / "nested")
            workspace = parent / "nested"
        elif path_kind == "project":
            workspace.mkdir()
            (workspace / "src").mkdir()
            # These authored UUID/time-shaped values must never be normalized.
            (workspace / "src/user.txt").write_bytes(
                b"2026-01-02T03:04:05+00:00 123e4567-e89b-42d3-a456-426614174000\r\n\xff")
            (workspace / "src/user.txt").chmod(0o640)
            (workspace / "user-link").symlink_to("src/user.txt")
        if workspace_literal is not None:
            operand = workspace_literal
            workspace = cwd / workspace_literal
        saved = snapshot(case)
        args = (["init", *extra, "--", operand] if terminator else
                ["init", *([] if operand is None else [operand]), *extra])
        old_mask = os.umask(mask)
        try:
            result = self.candidate(args, cwd, env)
            assert result[0] == 0 and not result[2], result
            actual = snapshot(case)
            for key, entry in saved.items():
                if entry[0] in ("file", "link"):
                    assert actual[key] == entry, f"authored entry changed: {key}"
            stamps, ids = generated_sequence(workspace)
            tree = snapshot(workspace)
            assert {p.name for p in (workspace / "state").iterdir()} == {
                "agents.json", "tasks.json", ".workspace.lock"}, "init created authority"
            assert tree["state/.workspace.lock"][:3] == ("file", 0o600, b"")
            assert tree["dashboard.md"][1] == 0o600
            for key, entry in tree.items():
                if entry[0] == "file" and key not in ("dashboard.md", "state/.workspace.lock", "src/user.txt"):
                    assert entry[1] == 0o666 & ~mask, (key, oct(entry[1]), oct(mask))
            for relative in ("coven.toml", "tmux/coven.toml"):
                tomllib.loads((workspace / relative).read_text())
            restore(case, saved)
            with mock.patch.object(coven, "now", side_effect=stamps) as clock, \
                    mock.patch.object(coven.uuid, "uuid4", side_effect=ids) as identity:
                expected_result = python(args, cwd, env)
                assert clock.call_count == len(stamps) and identity.call_count == len(ids)
            expected = snapshot(case)
            assert result == expected_result, (result, expected_result)
            different = {key: (actual.get(key, ())[:3], expected.get(key, ())[:3])
                         for key in actual.keys() | expected.keys()
                         if actual.get(key, ())[:3] != expected.get(key, ())[:3]}
            assert not different, repr(different)[:14000]
            if interop:
                # Leave a fresh native workspace, not the oracle's workspace.
                restore(case, saved)
                assert self.candidate(args, cwd, env)[0] == 0
                before = snapshot(workspace)
                refresh = self.candidate(["refresh", workspace], cwd, env)
                assert refresh[0] == 0 and not refresh[2], refresh
                after = snapshot(workspace)
                for key in before:
                    if key != "dashboard.md":
                        assert after[key][:3] == before[key][:3], f"refresh changed {key}"
                with mock.patch.dict(os.environ, env, clear=True):
                    state = coven.load_workspace_state(workspace)
                    assert state.team["agents"]
                mutation = python(["task", "add", workspace, "Authored after native init",
                                   "--owner", state.team["agents"][0]], cwd, env)
                assert mutation[0] == 0, mutation
                native_read = self.candidate(["task", "list", workspace, "--json"], cwd, env)
                oracle_read = python(["task", "list", workspace, "--json"], cwd, env)
                assert native_read[0] == oracle_read[0] == 0, (native_read, oracle_read)
                assert json.loads(native_read[1]) == json.loads(oracle_read[1])
                assert self.candidate(["refresh", workspace], cwd, env)[0] == 0
        finally:
            os.umask(old_mask)

    def reject(self, case, cwd, operand, extra=(), overrides=None, code=1, pattern=None, before=()):
        env = {**ENV, **(overrides or {})}
        args = ["init", *before, str(operand), *extra]
        before = snapshot(case)
        results = [python(args, cwd, env)]
        assert snapshot(case) == before, "Python refusal changed files/metadata"
        results.append(self.candidate(args, cwd, env))
        assert snapshot(case) == before, "native refusal changed bytes/inodes/modes/mtime or created first lock"
        for result in results:
            assert result[0] == code and not result[1] and result[2], result
            if pattern:
                assert re.search(pattern, result[2], re.I), result

    def collision(self, name, kind, flags):
        case, cwd, workspace = self.fixture()
        workspace.mkdir()
        path = workspace / name
        if kind == "file":
            path.write_bytes(b"Keep authored bytes\r\n\xff")
            path.chmod(0o640)
        elif kind == "directory":
            path.mkdir(mode=0o750)
            (path / "sentinel").write_bytes(b"Keep nested data")
        elif kind == "fifo":
            os.mkfifo(path, 0o620)
        else:
            outside = case / "outside"
            if kind == "live-link":
                outside.mkdir()
                (outside / "sentinel").write_bytes(b"Keep outside data")
            path.symlink_to(outside)
        self.reject(case, cwd, workspace, flags, pattern=RESERVED_ERROR)

    def initialized(self, kind):
        case, cwd, workspace = self.fixture()
        result = python(["init", workspace, "--agents", "operator"], cwd, ENV)
        assert result[0] == 0, result
        (workspace / "goal.md").write_bytes(b"# Authored goal\n")
        (workspace / "work/dirty.txt").write_bytes(b"uncommitted authored work\n")
        if kind == "malformed":
            (workspace / "coven.json").write_bytes(b"{broken\xff")
        elif kind.startswith("ledger"):
            revision = coven.read_task_snapshot(workspace)[0]
            result = python(["state", "import-tasks", workspace, "--expect-revision", revision, "--json"], cwd, ENV)
            assert result[0] == 0, result
            if kind == "ledger-pending":
                (workspace / task_ledger.MARKER).unlink()
            elif kind == "ledger-malformed":
                (workspace / task_ledger.MARKER).write_bytes(b"{broken")
        elif kind.startswith("action"):
            with storage.transport_gate(workspace, workspace / "state/.runtime-transport.lock", exclusive=True) as gate:
                with storage.workspace_lock(workspace, workspace / "state/.workspace.lock") as held:
                    actions.ActionStore(workspace).enable(held, gate=gate)
            if kind == "action-malformed":
                (workspace / actions.CONTROL).write_bytes(b"{broken")
            elif kind == "action-pending":
                (workspace / actions.CONTROL).unlink()
                (workspace / actions.BUNDLES).mkdir(parents=True, exist_ok=True)
                (workspace / actions.BUNDLES / "orphan.json").write_bytes(b"{}")
        elif kind.startswith("execution"):
            result = python(["execution", "enable", workspace, "--expect-execution-revision",
                             task_attempts.DISABLED, "--request-id", "enable", "--json"], cwd, ENV)
            assert result[0] == 0, result
            if kind == "execution-pending":
                (workspace / task_attempts.CONTROL).unlink()
            elif kind == "execution-malformed":
                (workspace / task_attempts.CONTROL).write_bytes(b"{broken")
        # Every refusal must precede lock acquisition, even for active authority.
        (workspace / "state/.workspace.lock").unlink(missing_ok=True)
        for flags in FLAGS:
            self.reject(case, cwd, workspace, flags, pattern=RESERVED_ERROR)

    def partial_write(self):
        case, cwd, workspace = self.fixture()
        workspace.mkdir()
        sentinel = workspace / "project.txt"
        sentinel.write_bytes(b"Authored data survives failed initialization\n")
        sentinel.chmod(0o640)
        saved = snapshot(case)
        # Keep every nondeterministic field beyond the real filesystem limit.
        name = "Partial-" + "x" * 160
        args = ["init", workspace, "--blank", "--name", name]
        prefix = (b'{\n  "version": 1,\n  "name": "' + name.encode())[:128]
        expected = None
        old_mask = os.umask(0o022)
        try:
            for native in (True, False):
                if not native:
                    restore(case, saved)
                before = snapshot(case)
                result = (self.candidate(args, cwd, ENV, limited=True) if native else
                          limited_python(args, cwd, ENV))
                assert result[0] == 1 and not result[1], result
                assert re.search(
                    r"Initialization stopped; partial files have been preserved for inspection|"
                    r"initialization_stopped_partial_files_preserved_for_inspection",
                    result[2], re.I), result
                after = snapshot(case)
                sentinel_key = str(sentinel.relative_to(case))
                assert after[sentinel_key] == before[sentinel_key], "partial init changed authored data"
                tree = snapshot(workspace)
                assert tree.keys() == {".", "project.txt", "coven.json"}, tree
                assert tree["coven.json"][:3] == ("file", 0o644, prefix), tree["coven.json"]
                comparable = {key: entry[:3] for key, entry in tree.items()}
                if expected is None:
                    expected = comparable
                else:
                    assert comparable == expected, "Python/native partial inventories differ"
                # The partial file must prevent all later adoption/reset attempts.
                for flags in FLAGS:
                    self.reject(case, cwd, workspace, flags, pattern=RESERVED_ERROR)
        finally:
            os.umask(old_mask)

    def corpus(self):
        self.run("default/full-example-and-interoperability", lambda: self.success(interop=True))
        self.run("blank/interoperability", lambda: self.success(["--blank"], interop=True))
        successes = [
            ("unicode-roster", ["--agents", " Alice \U0001f680 , Dr Oom ,JAMAL", "--name", "Team \u03bb \U0001f680"]),
            ("empty-name-default", ["--name", ""]),
            ("example-slug", ["--example", " Interactive Demo "]),
            ("omitted-owners", ["--agents", "Jamal,Reviewer"]),
            ("blank-ignores-example", ["--blank", "--example", "../nonexistent"]),
            ("repeated-options-last-wins", ["--name", "!!!", "--name", "Last", "--agents", "!", "--agents", "A,B",
                                           "--multiplexer", "tmux", "--multiplexer", "herdr",
                                           "--opencode-command", "", "--opencode-command", "oc",
                                           "--example", "missing", "--example", "interactive-demo"]),
            ("literal-uuid-and-timestamp-input", ["--name", "123e4567-e89b-42d3-a456-426614174000",
                "--opencode-command", "echo 2026-01-02T03:04:05+00:00 123e4567-e89b-42d3-a456-426614174000"]),
            ("abbreviated-options", ["--agen", "A,B", "--na", "Name", "--op", "oc", "--mu", "tmux", "--bla", "--fo"]),
            ("repeated-booleans", ["--blank", "--blank", "--force", "--force"]),
            ("negative-name-separated", ["--blank", "--name", "-1team"]),
            ("negative-name-equals", ["--blank", "--name=-1team"]),
            ("negative-agents", ["--blank", "--agents", "-1agent"]),
            ("negative-raw-command", ["--blank", "--opencode-command", "-1runner"]),
            ("negative-fraction-values", ["--blank", "--name", "-.5suffix", "--agents", "-.5agent",
                                          "--opencode-command", "-.5runner"]),
            ("option-like-name-equals", ["--blank", "--name=-unknown"]),
        ]
        for label, flags in successes:
            self.run(label, lambda f=flags: self.success(f))
        for mux in ("herdr", "tmux"):
            for command in ("  oc --model 'quoted value'  ", " runner \"quoted\"\tline\nnext\x7f ", " oc\t--raw "):
                self.run(f"raw-command/{mux}/{command!r}",
                         lambda m=mux, c=command: self.success(["--multiplexer", m, "--opencode-command", c]))
            for override in ("", " TMUX ", "herdr"):
                self.run(f"mux-env/{mux}/{override!r}", lambda m=mux, o=override:
                         self.success(["--multiplexer", m], overrides={"COVEN_MULTIPLEXER": o}))
        for kind in ("missing", "nested", "unicode", "dotdot", "cwd", "dot", "empty", "relative", "tilde",
                     "symlink-root", "dangling-root", "symlink-parent", "project"):
            self.run(f"path/{kind}", lambda k=kind: self.success(["--blank"], path_kind=k))
        for literal in ("-2026-demo", "-.5suffix"):
            for terminator in (False, True):
                self.run(f"parser/workspace/{literal}/terminator={terminator}", lambda l=literal, t=terminator:
                         self.success(["--blank"], workspace_literal=l, terminator=t))
        for literal in ("-inf", "-nan", "-unknown", "--json"):
            self.run(f"parser/literal-after-terminator/{literal}", lambda l=literal:
                     self.success(["--blank"], workspace_literal=l, terminator=True))
        for mask in (0o000, 0o027, 0o077):
            self.run(f"creation-modes/{mask:o}", lambda m=mask: self.success(["--blank"], mask=m))
        for name in RESERVED:
            for kind in ("file", "directory", "dangling-link", "live-link", "fifo"):
                for flags in FLAGS:
                    self.run(f"reserved/{name}/{kind}/{flags}",
                             lambda n=name, k=kind, f=flags: self.collision(n, k, f))
        for kind in ("valid", "malformed", "ledger-active", "ledger-pending", "ledger-malformed",
                     "action-active", "action-pending", "action-malformed",
                     "execution-active", "execution-pending", "execution-malformed"):
            self.run(f"initialized/{kind}/all-flags", lambda k=kind: self.initialized(k))
        invalid = [(["--agents", value], 1) for value in ("", "_", "\U0001f680", "a,", ",a", "a,,b", "A,a", "Dr Oom,dr-oom")]
        invalid += [(["--name", "!!!"], 1), (["--name", "   "], 1),
                    (["--opencode-command", ""], 1), (["--opencode-command", " \t\n"], 1)]
        invalid += [(["--example", value], 1) for value in ("", "!", "missing-example", "../missing")]
        invalid += [(flags, 2) for flags in (["--multiplexer", "TMUX"], ["--multiplexer", " tmux "],
                    ["--multiplexer", "invalid", "--multiplexer", "tmux"],
                    ["--multiplexer", "unknown"], ["--json"], ["--blank=true"], ["--force=false"],
                    ["--name"], ["--agents"], ["extra-operand"], ["--unknown"], ["--"] + ["extra", "operand"])]
        invalid += [(flags, 2) for flags in (["--name", "--blank"], ["--na"], ["--agen"], ["--op"],
                    ["--mu"], ["--ex"], ["--na", "--blank"], ["--agen", "--blank"],
                    ["--op", "--blank"], ["--mu", "--blank"], ["--ex", "--blank"],
                    ["--unknown", "--blank"], ["--", "--unknown"], ["--", "--blank"])]
        invalid += [([option, literal], 2) for option in ("--name", "--agents", "--opencode-command")
                    for literal in ("-inf", "-nan", "-unknown")]
        for flags, code in invalid:
            def bad(flags=flags, code=code):
                case, cwd, workspace = self.fixture()
                self.reject(case, cwd, workspace / "missing" / "nested", flags, code=code)
            self.run(f"invalid/{flags!r}", bad)
        for literal in ("-inf", "-nan", "-unknown"):
            def bad_operand(literal=literal):
                case, cwd, _ = self.fixture()
                self.reject(case, cwd, literal, ["--blank"], code=2)
            self.run(f"parser/refused-workspace/{literal}", bad_operand)
        for before in (("--unknown",), ("--",)):
            def bad_order(before=before):
                case, cwd, workspace = self.fixture()
                self.reject(case, cwd, workspace, ["--blank"], before=before, code=2)
            self.run(f"parser/unknown-or-terminator-before-workspace/{before}", bad_order)
        self.run("operational/partial-write-file-size-limit", self.partial_write)
        for value in ("unknown", " \t "):
            def bad_env(value=value):
                case, cwd, workspace = self.fixture()
                self.reject(case, cwd, workspace, overrides={"COVEN_MULTIPLEXER": value})
            self.run(f"invalid-env/{value!r}", bad_env)
        for kind in ("file", "fifo"):
            def not_directory(kind=kind):
                case, cwd, workspace = self.fixture()
                if kind == "file":
                    workspace.write_bytes(b"not a directory")
                elif kind == "fifo":
                    os.mkfifo(workspace)
                self.reject(case, cwd, workspace)
            self.run(f"workspace-type/{kind}", not_directory)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--binary")
    parser.add_argument("--oracle-only", action="store_true")
    args = parser.parse_args()
    assert args.binary or args.oracle_only, "--binary required unless --oracle-only"
    binary = str(Path(args.binary).resolve()) if args.binary else None
    def expired(signum, frame):
        raise CorpusTimeout("init corpus exceeded 100 seconds")
    signal.signal(signal.SIGALRM, expired)
    signal.alarm(100)
    started = time.monotonic()
    try:
        with tempfile.TemporaryDirectory(prefix="coven-init-") as folder:
            root = Path(folder)
            empty = root / "empty-path"
            empty.mkdir()
            ENV.update(PATH=str(empty), HOME=str(root))
            suite = Suite(root, binary, args.oracle_only)
            with mock.patch.dict(os.environ, ENV, clear=True):
                suite.corpus()
            print(f"init parity: {suite.count} cases, {len(suite.failures)} failures, {time.monotonic() - started:.2f}s")
            for failure in suite.failures:
                print(failure, file=sys.stderr)
            return bool(suite.failures)
    finally:
        signal.alarm(0)
        for child in tuple(CHILDREN):
            stop(child)


if __name__ == "__main__":
    raise SystemExit(main())
